<?php require_once __DIR__.'/includes/app.php';require_login();verify_csrf();$action=$_POST['action']??'';if($action==='test'){$to=setting('whatsapp_test_number');$msg='Trial Manager test message sent at '.now_sql();$ok=send_whatsapp_cloud($to,$msg);flash($ok?'success':'danger',$ok?'Test WhatsApp sent.':'Test WhatsApp failed.');redirect('integrations.php');}$id=(int)($_POST['request_id']??0);$r=one('SELECT * FROM trial_requests WHERE id=?',[$id]);if(!$r){flash('danger','Request not found.');redirect('trial-requests.php');}$to=setting('whatsapp_admin_number',$r['whatsapp']);$msg=render_trial_message($r);$ok=send_whatsapp_cloud($to,$msg,$id);create_notification($ok?'whatsapp.sent':'whatsapp.failed','whatsapp',$ok?'WhatsApp sent':'WhatsApp failed','Request #'.$id,['trial_request_id'=>$id]);flash($ok?'success':'danger',$ok?'WhatsApp notification sent.':'WhatsApp notification failed.');redirect('request-view.php?id='.$id);
